package com.projecteden.village.domain;
import java.time.LocalDateTime;import com.projecteden.character.domain.Character;import jakarta.persistence.*;
@Entity@Table(name="village_changes",uniqueConstraints=@UniqueConstraint(columnNames={"character_id","change_type"}))public class VillageChange{
	@Id@GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="character_id",nullable=false)private Character character;@Enumerated(EnumType.STRING)@Column(nullable=false)private VillageCategory category;@Enumerated(EnumType.STRING)@Column(name="change_type",nullable=false)private VillageChangeType changeType;@Column(nullable=false)private boolean appeared;private LocalDateTime appearedAt;private LocalDateTime createdAt;private LocalDateTime updatedAt;
	protected VillageChange(){}private VillageChange(Character character,VillageCategory category,VillageChangeType changeType,LocalDateTime now){this.character=character;this.category=category;this.changeType=changeType;this.appeared=true;this.appearedAt=now;}public static VillageChange appear(Character character,VillageCategory category,VillageChangeType changeType,LocalDateTime now){return new VillageChange(character,category,changeType,now);}@PrePersist void prePersist(){LocalDateTime now=LocalDateTime.now();createdAt=now;updatedAt=now;}@PreUpdate void preUpdate(){updatedAt=LocalDateTime.now();}
	public Long getId(){return id;}public Character getCharacter(){return character;}public VillageCategory getCategory(){return category;}public VillageChangeType getChangeType(){return changeType;}public boolean isAppeared(){return appeared;}public LocalDateTime getAppearedAt(){return appearedAt;}
}
